<script setup>
import { computed, ref } from 'vue';
import CircuitScene from './components/CircuitScene.vue';
import ComponentLibrary from './components/ComponentLibrary.vue';
import SchematicView from './components/SchematicView.vue';
import { formatCurrent, simulateCircuit } from './engine/simulator';
const view=ref('3d'), exercise=ref('led'), selected=ref({name:'Breadboard (830)',value:'830 puntos',pins:['A–E','F–J','+','−'],description:'Protoboard sin soldadura con rieles de alimentación.'}), placed=ref(['breadboard','battery','resistor','led']);
const result=computed(()=>simulateCircuit(exercise.value)); const status=computed(()=>({...result.value,currentLabel:formatCurrent(result.value.current)}));
function add(component){placed.value.push(component.id);selected.value=component}
</script>
<template><div class="lab-shell"><header class="lab-topbar"><div class="lab-logo"><span>⌁</span></div><nav><button>Archivo⌄</button><button>Editar⌄</button><button>Vista⌄</button></nav><div class="document-title"><i></i><strong>Mi primer circuito</strong><small>LOCAL</small></div><div class="top-status"><span class="healthy" :class="status.status">⌁ {{status.label}}</span><button class="top-control" :class="{active:view==='3d'}" @click="view='3d'">3D</button><button class="top-control" :class="{active:view==='diagram'}" @click="view='diagram'">Esquema</button><button class="run-control" @click="exercise=exercise==='led'?'overload':'led'">{{exercise==='led'?'Ⅱ Pausar':'▶ Ejecutar'}}</button><button class="top-control" @click="exercise='led'">Reset</button></div></header><div class="lab-body"><ComponentLibrary :selected-id="selected?.id" @select="selected=$event" @add="add"/><main class="lab-center"><section class="lab-canvas" :class="`state-${status.status}`"><CircuitScene v-if="view==='3d'"/><SchematicView v-else/><div class="canvas-badge"><b>{{status.label}}</b><span>{{status.currentLabel}} · {{status.voltage.toFixed(1)}} V</span></div><div class="canvas-tools"><button>＋</button><button>−</button><button>⌖</button></div></section><section class="analysis-panel"><header><div><strong>⌁ Análisis</strong><span>{{status.detail}}</span></div><div class="analysis-actions"><button @click="exercise='divider'">Divisor</button><button @click="exercise='inverter'">Inversor</button><button @click="exercise='short'">Corto</button></div></header><div class="analysis-content"><aside><span>CANALES</span><strong>{{placed.length}} / 12</strong><p>Selecciona nodos para comparar voltaje y corriente.</p></aside><div class="scope"><svg viewBox="0 0 700 180"><path d="M0 105 C35 105 35 45 70 45 S105 140 140 140 175 50 210 50 245 130 280 130 315 45 350 45 385 135 420 135 455 55 490 55 525 125 560 125 595 45 630 45 665 105 700 105"/></svg><span>{{status.status==='ok'?'SEÑAL ESTABLE':status.status==='warn'?'LÍMITE SUPERADO':'FALLO DETECTADO'}}</span></div></div></section></main><aside class="properties-panel"><div class="property-tabs"><button class="active">Inspector</button><button>Diagnóstico</button></div><div class="property-body"><span class="eyebrow">Propiedades</span><h2>{{selected?.name||'Sin selección'}}</h2><code>{{selected?.id||'breadboard-main'}}</code><label>Nombre<input :value="selected?.name||''" readonly></label><dl><div><dt>Valor</dt><dd>{{selected?.value||'—'}}</dd></div><div><dt>Pines</dt><dd>{{selected?.pins?.join(' · ')||'—'}}</dd></div><div><dt>Voltaje</dt><dd>{{status.voltage.toFixed(2)}} V</dd></div><div><dt>Corriente</dt><dd>{{status.currentLabel}}</dd></div></dl><div class="diagnostic" :class="status.status"><b>{{status.label}}</b><p>{{status.detail}}</p></div><h3>LECTURAS EN VIVO</h3><p class="live-reading">P = {{Number.isFinite(status.power)?status.power.toFixed(3):'∞'}} W<br>Vout = {{Number.isFinite(status.output)?status.output.toFixed(2):'∞'}} V</p></div></aside></div></div></template>
